// TestDescribeLayout is the spec floor for the descriptor's additive layout
// field (fix-tv-unblock-2, packaged-playback "Playback descriptor and verb
// split", the layout paragraph): an hls answer carries the build's audio
// layout — the value the lane persisted at publish, the layoutName vocabulary
// verbatim ("single-variant" | "rendition") — while a namespace predating the
// record answers no layout (fail-open: the client mounts as before) and a
// direct answer never carries one. The projection is read-side only: the
// stored record answers verbatim, no read-side composition.
func TestDescribeLayout(t *testing.T) {
	// A partial namespace answers hls without an on-disk build (the integrity
	// guard exempts partial builds) — the cheapest honest hls fixture, the
	// describe_codecs_test precedent.
	hlsDoc := func(streams map[string]any) map[string]any {
		return map[string]any{"streams": streams}
	}

	s := &Service{Secret: []byte("k"), Root: t.TempDir()}

	// Scenario: Packaged descriptor names the build's layout.
	t.Run("rendition_build_answers_rendition", func(t *testing.T) {
		d := hlsDoc(map[string]any{
			"state":    StatePartial,
			"playlist": "/media/it/n0/index.m3u8",
			"layout":   "rendition",
		})
		mode, _, playURL, _, _, _, _, _, layout := s.Describe("it", d)
		if mode != ModeHls {
			t.Fatalf("mode = %q, want hls", mode)
		}
		if layout != "rendition" {
			t.Fatalf("layout = %q, want the persisted record verbatim", layout)
		}
		if !strings.HasPrefix(playURL, "/media/it/n0/index.m3u8?"+tokenQuery+"=") {
			t.Fatalf("playURL = %q, want the playable playlist URL retained", playURL)
		}
	})

	t.Run("single_variant_build_answers_single_variant", func(t *testing.T) {
		d := hlsDoc(map[string]any{
			"state":    StatePartial,
			"playlist": "/media/it/n0/index.m3u8",
			"layout":   "single-variant",
		})
		mode, _, _, _, _, _, _, _, layout := s.Describe("it", d)
		if mode != ModeHls {
			t.Fatalf("mode = %q, want hls", mode)
		}
		if layout != "single-variant" {
			t.Fatalf("layout = %q, want the persisted record verbatim", layout)
		}
	})

	// Scenario: a namespace predating the record answers no layout and the
	// play_url unchanged (fail-open — the codecs precedent).
	t.Run("pre_record_namespace_fails_open_with_play_url_unchanged", func(t *testing.T) {
		d := hlsDoc(map[string]any{
			"state":    StatePartial,
			"playlist": "/media/it/n0/index.m3u8",
		})
		mode, _, playURL, _, _, _, _, _, layout := s.Describe("it", d)
		if mode != ModeHls {
			t.Fatalf("mode = %q, want hls", mode)
		}
		if layout != "" {
			t.Fatalf("layout = %q, want empty — a pre-record namespace must fail open", layout)
		}
		if !strings.HasPrefix(playURL, "/media/it/n0/index.m3u8?"+tokenQuery+"=") {
			t.Fatalf("playURL = %q, want the playable playlist URL unchanged", playURL)
		}
	})

	t.Run("unreadable_record_degrades_to_absent", func(t *testing.T) {
		d := hlsDoc(map[string]any{
			"state":    StatePartial,
			"playlist": "/media/it/n0/index.m3u8",
			"layout":   42, // an unreadable record is no record at all
		})
		_, _, _, _, _, _, _, _, layout := s.Describe("it", d)
		if layout != "" {
			t.Fatalf("layout = %q, want empty behind an unreadable record", layout)
		}
	})

	// Scenario: a direct answer never carries the layout — the field
	// describes the pack.
	t.Run("direct_answers_never_carry_layout", func(t *testing.T) {
		d := map[string]any{"streams": map[string]any{
			"state":  StateFailed,
			"layout": "rendition", // even a failed namespace that once carried one
		}}
		mode, _, _, _, _, _, _, _, layout := s.Describe("it", d)
		if mode != ModeDirect {
			t.Fatalf("mode = %q, want direct", mode)
		}
		if layout != "" {
			t.Fatalf("layout = %q, want empty on a direct answer", layout)
		}
	})
}
